import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Bir görsele filigran eklemek dakikalar sürer. Program kurmazsınız, fotoğrafınız cihazınızdan ayrılmaz ve sonunda korumalı bir görsel indirirsiniz.</p>\n<p>Bu yazı, işlemi altı adımda anlatıyor. İster metin ister logo filigranı ekleyin, adımlar aynıdır.</p>\n<p>Sonunda metin ve logo arasında nasıl seçim yapacağınızı, opaklığı nasıl ayarlayacağınızı ve toplu filigranlamayı öğreneceksiniz.</p>\n<h2 id=\"before-you-start\">Başlamadan önce: neler gerekli</h2>\n<p>Tek ihtiyacınız, filigranlanacak fotoğraflar ve modern bir tarayıcıdır. Logo kullanacaksanız logo dosyanızı hazırlayın.</p>\n<p>Logo PNG olmalıdır. PNG saydamlığı destekler; logo arka plansız durur.</p>\n<p>Filigran metnini belirleyin. Adınız, siteniz ya da markanız; kısa tutun.</p>\n<h2 id=\"step-by-step\">Filigran ekleme altı adımda</h2>\n<p>Önce aracı açın ve fotoğrafı yükleyin. Önizlemede fotoğrafın tamamını görün.</p>\n<p>Sonra filigran türünü seçin: metin ya da logo. Konumu, opaklığı ve boyutu ayarlayın.</p>\n<p>Son olarak sonucu kontrol edip indirin. Önizlemeyi atlamayın; yanlış filigran zaman kaybıdır.</p>\n<ol>\n<li>Filigran aracını açın ve fotoğrafınızı yükleyin.</li>\n<li>Metin filigranı yazın ya da logo dosyanızı yükleyin.</li>\n<li>Konumu seçin; köşe yerine kenar ortası daha güvenlidir.</li>\n<li>Opaklığı ayarlayın; önizlemede yüzde 40-50 kullanın.</li>\n<li>Boyutu ve açıyı ayarlayın.</li>\n<li>Sonucu önizlemede kontrol edip indirin.</li>\n</ol>\n<h2 id=\"choosing-text-or-logo\">Metin ve logo filigranı arasında seçim</h2>\n<p>Acele ediyorsanız metin filigranı yazın; adınızı yazmanız yeterli, logo dosyası aramanıza gerek kalmaz.</p>\n<p>Logo filigranı kullanın; marka işaretiniz, çalışmanızı daha profesyonel ve tanınır gösterir.</p>\n<p>Seçim amaca bağlıdır. Hızlı koruma için metin, marka için logo kullanın.</p>\n<h2 id=\"typing-watermark-text\">Filigran metnini yazmak</h2>\n<p>Metni kısa tutun. Adınız ya da siteniz yeterlidir; uzun cümleler okunamaz.</p>\n<p>Yazı tipini sade seçin. Karmaşık yazı tipleri küçük boyutta okunamaz.</p>\n<p>Metni büyük harfle yazmayın. Büyük harf, filigranı baskın gösterir.</p>\n<h2 id=\"uploading-a-logo\">Logonuzu filigran olarak yüklemek</h2>\n<p>Logo dosyanızı seçin. PNG olmalıdır; saydamlık korunur.</p>\n<p>Logoyu yüksek çözünürlükte hazırlayın. Küçük logo büyütülünce bulanıklaşır.</p>\n<p>Logonun boyutunu ayarlayın. Fotoğraf boyutunun yüzde 5-10'u iyi bir başlangıçtır.</p>\n<h2 id=\"choosing-placement\">Filigranın yerini seçmek</h2>\n<p>Köşe en yaygın yerdir ama en kolay kırpılan yerdir. Köşedeki filigran, kırpmayla gider.</p>\n<p>Merkez, en güvenli yerdir ama fotoğrafı böler. Önizlemelerde merkez kullanılır.</p>\n<p>Kenar ortası iyi bir denge sunar. Kırpması zordur ve fotoğrafı az böler.</p>\n<h2 id=\"setting-opacity\">Opaklığı ayarlamak</h2>\n<p>Opaklık kaydırıcısıyla filigranın belirginliğini ayarlayın. Yüzde 100 opak filigran fotoğrafı kapatır.</p>\n<p>Müşteriye önizleme gönderirken opaklığı yüzde 40-50 ayarlayın; filigran okunur ama fotoğraf da net görülür.</p>\n<p>Sosyal medyada yüzde 20-30 yeterlidir. Hafif filigran markayı duyurur ama görseli bozmaz.</p>\n<h2 id=\"setting-size\">Filigran boyutunu ayarlamak</h2>\n<p>Boyut kaydırıcısıyla filigranı büyütüp küçültün. Fotoğraf boyutunun yüzde 5-10'u iyi bir başlangıçtır.</p>\n<p>Küçük fotoğrafa büyük filigran koymayın; filigran boyunu fotoğrafın boyutuna göre ayarlayın.</p>\n<p>Toplu filigranlamada boyutu orantılı tutun. Tüm fotoğraflarda aynı görünmelidir.</p>\n<h2 id=\"setting-rotation\">Döndürme açısını ayarlamak</h2>\n<p>Açı kaydırıcısıyla filigranı döndürün. 45 derecelik çapraz filigran, kırpması zor bir işarettir.</p>\n<p>Çapraz filigran, önizlemelerde kullanılır. Final görsellerde düz filigran daha zariftir.</p>\n<p>Açıyı abartmayın. Hafif eğik filigran zarif görünür; dik filigran dikkat dağıtır.</p>\n<h2 id=\"tiled-repeat-mode\">Döşemeli tekrar modunu kullanmak</h2>\n<p>Döşemeli mod, filigranı görselin her yerine tekrarlar. Kırpmayla kurtulmak imkânsız hâle gelir.</p>\n<p>Bu mod, müşteri önizlemelerinde kullanılır. Müşteri fotoğrafı görür ama izinsiz kullanamaz.</p>\n<p>Desen opaklığını düşük tutun. Fotoğraf hâlâ görülmelidir.</p>\n<h2 id=\"preview-and-compare\">İndirmeden önce önizlemeyi kontrol etmek</h2>\n<p>Her zaman önizlemeyi kontrol edin. Filigranın konumu, boyutu ve opaklığı doğru olmalıdır.</p>\n<p>Karşılaştırma görünümüyle orijinali ve filigranlı sürümü yan yana inceleyin. Fotoğraf hâlâ görülüyor mu?</p>\n<p>Şüphede kalırsanız opaklığı azaltın. Hafif filigran, ağır filigrandan her zaman iyidir.</p>\n<h2 id=\"choosing-export-format\">Dışa aktarma formatını seçmek</h2>\n<p>Fotoğrafları JPG olarak dışa aktarın. Hafif dosyalar her yerde açılır.</p>\n<p>Logo saydam olacaksa PNG kullanın. JPG, arka planı beyaz yapar.</p>\n<p>Kaliteyi yüzde 85-90 arasında tutun. Dosya küçülür, görünüm değişmez.</p>\n<h2 id=\"watermarking-on-mobile\">Telefon ve tablette filigranlamak</h2>\n<p>Filigran aracını telefon tarayıcısında açın, fotoğrafı yükleyin ve filigranı parmağınızla konumlandırın.</p>\n<p>Telefonda küçük ayarlar zordur. Hassas konum için bilgisayarı tercih edin.</p>\n<p>İndirilen dosyalar İndirilenler klasörüne gider. Dosyayı bulamazsanız tarayıcının indirme listesine bakın.</p>\n<h2 id=\"troubleshooting\">Filigranla yaygın sorunları çözmek</h2>\n<p>Filigran görünmüyorsa opaklığı kontrol edin. Yüzde 10'un altındaki opaklık, çoğu fotoğrafta kaybolur.</p>\n<p>Filigran bazı bölgelerde kayboluyorsa kontur ekleyin. Beyaz yazıya siyah kontur, her zeminde görünür.</p>\n<p>Logo beyaz kutuyla geliyorsa dosya PNG değildir. Logoyu saydam PNG olarak hazırlayın.</p>\n<h2 id=\"quick-tips\">Daha iyi filigranlar için hızlı ipuçları</h2>\n<p>Metni kısa tutun. Adınız ya da siteniz yeterlidir.</p>\n<p>Opaklığı düşük tutun. Fotoğraf hâlâ görülmelidir.</p>\n<p>Her fotoğrafta aynı filigranı kullanın. Tutarlılık marka bilinirliği yaratır.</p>\n<h2 id=\"watermarking-a-batch\">Bir grup fotoğrafı filigranlamak</h2>\n<p>Tüm fotoğrafları aynı anda yükleyin. Araç, her birine aynı filigranı uygular.</p>\n<p>Toplu filigranlamada aynı ayarları kullanın. Tutarlılık, seti profesyonel gösterir.</p>\n<p>Filigranlı dosyaları ZIP olarak indirin. Tek indirme, tüm dosyaları düzenli biçimde verir.</p>\n<p>Adım adım ilerleyin ve her fotoğrafı indirmeden önce kontrol edin. Kılavuzun tamamı için <a href=\"/tr/blog/gorsel-filigran-rehberi\">Filigran kılavuzuna</a> bakın; en iyi uygulamalar için <a href=\"/tr/blog/filigran-en-iyi-uygulamalar\">filigran en iyi uygulamaları</a> yazısı yardımcı olur. Metin için <a href=\"/tr/gorsele-metin-ekle\">görsele metin ekleme</a> hazırdır; araç ise <a href=\"/tr/gorsel-filigran-ekle\">görsel filigran</a> sayfasındadır.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Telefonda bir fotoğrafa filigran nasıl eklerim?","answer":"Filigran aracını telefon tarayıcısında açın, fotoğrafı yükleyin ve filigranı parmağınızla konumlandırın. Metin yazın ya da logo yükleyin, opaklığı ayarlayın ve indirin. Hassas konum için bilgisayarı tercih edin."},{"question":"Fotoğrafta filigran için en iyi konum neresidir?","answer":"Kenar ortası iyi bir dengedir; kırpması zordur ve fotoğrafı az böler. Köşe en kolay kırpılan yerdir. Merkez en güvenlidir ama fotoğrafı böler; önizlemelerde merkez kullanın."},{"question":"Birden fazla fotoğrafı aynı anda filigranlayabilir miyim?","answer":"Evet. Tüm fotoğrafları aynı anda yükleyin; araç her birine aynı filigranı uygular. Tutarlılık için aynı ayarları kullanın ve sonuçları ZIP olarak indirin."},{"question":"Filigranım fotoğrafın bazı bölgelerinde neden görünmez?","answer":"Çünkü filigran rengi arka planla aynıdır; beyaz filigran açık fotoğrafta kaybolur. Kontur ekleyin: beyaz yazıya siyah kontur, her zeminde görünür. Opaklığı da kontrol edin."},{"question":"Kırpılamayan bir filigran nasıl yaparım?","answer":"Döşemeli tekrar modu kullanın. Filigran görselin her yerine tekrarlanır; kırpmayla kurtulmak imkânsız hâle gelir. Bu mod, müşteri önizlemeleri için idealdir."},{"question":"Filigran eklemek görselin dosya boyutunu değiştirir mi?","answer":"Çok az. Filigran, görselin üzerine küçük bir işaret ekler; dosya boyutu neredeyse aynı kalır. Dışa aktarma formatı ve kalite, boyutu filigrandan çok daha fazla etkiler."}];
